namespace BrewNest.Modules.Returns.Domain.Entities;
internal abstract class ReturnDocument { public Guid Id{get;set;}public string Number{get;set;}=string.Empty;public DateTimeOffset CreatedAt{get;set;}public string CreatedBy{get;set;}=string.Empty;public DateTimeOffset? ModifiedAt{get;set;}public string? ModifiedBy{get;set;}public byte[] RowVersion{get;set;}=[]; }
