internal sealed class ReturnRequest:ReturnDocument { public string RmaNumber{get;set;}=string.Empty;public Guid SalesOrderId{get;set;}public string OrderNumber{get;set;}=string.Empty;public Guid BillId{get;set;}public string BillNumber{get;set;}=string.Empty;public string Reason{get;set;}=string.Empty;public RequestStatus Status{get;set;}public string? CreditNoteNumber{get;set;}public string? RefundReference{get;set;}public List<ReturnRequestLine> Lines{get;set;}=[];public List<ReturnApproval> Approvals{get;set;}=[]; }
