internal sealed class ReturnApproval { public Guid Id{get;set;}public Guid? ReturnRequestId{get;set;}public ReturnRequest? ReturnRequest{get;set;}public Guid? VoidRequestId{get;set;}public VoidRequest? VoidRequest{get;set;}public int Sequence{get;set;}public string RequiredRole{get;set;}=string.Empty;public string Decision{get;set;}="Pending";public string? DecidedBy{get;set;}public DateTimeOffset? DecidedAt{get;set;}public string? Remarks{get;set;} }
